'use strict';
const selectionBase={modalContent,handleAction,closeModal};
function selectionFiles(p=modalData){return libSelected().filter(d=>!p.query||d.name.toLowerCase().includes(p.query.toLowerCase())||(d.space+' / '+folderPath(d.folder)).toLowerCase().includes(p.query.toLowerCase()));}
function selectionInit(p=modalData){p.query??='';p.removeIds??=[];const selected=new Set(state.librarySelected);p.removeIds=p.removeIds.filter(id=>selected.has(id));return p;}
function selectionPaint(reset=false){modalData.scrollTop=reset?0:($('.selection-table-scroll')?.scrollTop||0);modalData.scrollLeft=$('.selection-table-scroll')?.scrollLeft||0;paintModal();}
function selectionRemove(ids,back=modalData){const remove=new Set(ids),count=state.librarySelected.filter(id=>remove.has(id)).length;state.librarySelected=state.librarySelected.filter(id=>!remove.has(id));back.removeIds=(back.removeIds||[]).filter(id=>!remove.has(id));persist();render();if(!libSelected().length){libraryReturn=null;selectionBase.closeModal();}else openModal('library-selected',back);toast('已从已选清单移除 '+count+' 份，原文件保留。');}
modalContent=function(){
 if(modal==='library-selected'){
  const p=selectionInit(),all=libSelected(),shown=selectionFiles(p),checked=new Set(p.removeIds),chosen=shown.filter(d=>checked.has(d.id)).length,ready=all.filter(d=>libStatus(d)==='解析完成').length;
  const table='<div class="selection-table-scroll"><table class="table selection-table"><thead><tr><th class="selection-check"><input type="checkbox" id="selection-check-all" data-selection-change="all" aria-label="勾选当前结果" aria-checked="'+(chosen&&chosen<shown.length?'mixed':chosen>0?'true':'false')+'" '+(shown.length&&chosen===shown.length?'checked':'')+' '+(!shown.length?'disabled':'')+'></th><th class="selection-index">序号</th><th class="selection-name">文件名称</th><th class="selection-status">解析状态</th><th class="selection-owner">所有者</th><th class="selection-location">位置</th><th class="selection-action">操作</th></tr></thead><tbody>'+shown.map((d,i)=>'<tr class="'+(checked.has(d.id)?'selection-checked':'')+'" data-selection-id="'+E(d.id)+'"><td><input type="checkbox" id="selection-row-'+E(d.id)+'" data-selection-change="row" data-id="'+E(d.id)+'" aria-label="勾选 '+E(d.name)+'" '+(checked.has(d.id)?'checked':'')+'></td><td class="selection-index">'+(i+1)+'</td><td><div class="row">'+ficon(d)+'<button type="button" class="filename" data-action="source" '+libAttrs(d)+' title="'+E(d.name)+'" '+(!auditFileAccess(d).preview?'disabled':'')+'>'+E(d.name)+'</button></div></td><td title="'+E(d.parseError||libStatus(d))+'">'+libStatusTag(d)+'</td><td title="'+E(d.owner||'当前用户')+'">'+E(d.owner||'当前用户')+'</td><td class="selection-location-cell" title="'+E(d.space+' / '+(folderPath(d.folder)||'根目录'))+'">'+E(d.space+' / '+(folderPath(d.folder)||'根目录'))+'</td><td>'+A('移除','selection-remove-one',libAttrs(d))+'</td></tr>').join('')+(!shown.length?'<tr><td colspan="7"><div class="selection-empty">没有符合条件的已选文件，请调整搜索条件。</div></td></tr>':'')+'</tbody></table></div>';
  requestAnimationFrame(()=>{if(modal!=='library-selected'||modalData!==p)return;const checkbox=$('[data-selection-change="all"]');if(checkbox)checkbox.indeterminate=chosen>0&&chosen<shown.length;const scroll=$('.selection-table-scroll');if(scroll){scroll.scrollTop=p.scrollTop||0;scroll.scrollLeft=p.scrollLeft||0;}});
  return modalFrame('已选文件','跨目录、跨空间保留；这里展示文件正文的解析状态。','<div class="selection-command"><div class="selection-summary"><span>已选 <strong>'+all.length+'</strong> 份</span><span>解析完成 <b>'+ready+'</b></span><span>解析未完成 <b>'+(all.length-ready)+'</b></span></div><div class="search">'+I('search','icon-sm')+'<input id="selection-query" aria-label="搜索已选文件或位置" placeholder="搜索文件或位置" data-selection-input="query" value="'+E(p.query)+'"></div></div><div class="selection-range"><span>'+(p.query?'找到 '+shown.length+' 份文件':'')+'</span><span>'+(checked.size?'待移除 '+checked.size+' 份':'勾选需要从清单移除的文件')+'</span></div>'+table,'<div class="selection-footer-note"><span>移除仅取消选择，原文件保留。</span>'+A('清空已选','lib-clear-selection-modal')+'</div><div class="row">'+B('批量移除'+(checked.size?'（'+checked.size+'）':''),'selection-remove-batch','danger',checked.size?'':'disabled')+B('关闭','close-modal','primary')+'</div>','selection-dialog');
 }
 if(modal==='selection-remove-confirm'){const p=modalData,ids=p.ids.filter(id=>state.librarySelected.includes(id));return modalFrame(p.all?'清空已选文件':'批量移除','只调整当前已选清单，不删除资料。','<p>确认从已选清单移除 <strong>'+ids.length+'</strong> 份文件？</p><div class="selection-confirm-list">'+ids.slice(0,5).map(id=>'<div>'+E(file(id)?.name||id)+'</div>').join('')+(ids.length>5?'<span>等 '+ids.length+' 份</span>':'')+'</div>',B('取消','close-modal')+B('确认移除','selection-confirm-remove','primary',ids.length?'':'disabled'),'small');}
 return selectionBase.modalContent();
};
handleAction=function(action,el){
 if(modal==='library-selected'){
  if(action==='source'){modalData.scrollTop=$('.selection-table-scroll')?.scrollTop||0;modalData.scrollLeft=$('.selection-table-scroll')?.scrollLeft||0;}
  if(action==='selection-remove-one'||action==='unselect-library'){selectionRemove([el.dataset.id]);return;}
  if(action==='selection-remove-batch'||action==='lib-clear-selection-modal'){const back=selectionInit(),all=action==='lib-clear-selection-modal',ids=all?[...state.librarySelected]:[...back.removeIds];if(!ids.length)return;back.scrollTop=$('.selection-table-scroll')?.scrollTop||0;openModal('selection-remove-confirm',{ids,back,all});return;}
 }
 if(action==='selection-confirm-remove'&&modal==='selection-remove-confirm'){selectionRemove(modalData.ids,modalData.back);return;}
 return selectionBase.handleAction(action,el);
};
closeModal=function(){if(modal==='selection-remove-confirm'){openModal('library-selected',modalData.back);return;}selectionBase.closeModal();};
window.addEventListener('input',e=>{if(modal!=='library-selected'||e.target.dataset.selectionInput!=='query')return;e.stopImmediatePropagation();modalData.query=e.target.value;selectionPaint(true);},true);
window.addEventListener('change',e=>{const kind=e.target.dataset.selectionChange;if(modal!=='library-selected'||!kind)return;e.stopImmediatePropagation();const p=selectionInit(),selected=new Set(p.removeIds);if(kind==='row'){if(e.target.checked)selected.add(e.target.dataset.id);else selected.delete(e.target.dataset.id);}else{for(const d of selectionFiles(p)){if(e.target.checked)selected.add(d.id);else selected.delete(d.id);}}p.removeIds=[...selected];selectionPaint();},true);
